use vstd::prelude::*;

verus! {

spec fn intersperse_seq(numbers: Seq<i32>, delim: i32) -> Seq<i32> {
    if numbers.len() == 0 {
        Seq::<i32>::empty()
    } else {
        Seq::new(2 * numbers.len() - 1, |k: int| {
            if k % 2 == 0 {
                numbers.index(k / 2)
            } else {
                delim
            }
        })
    }
}

fn intersperse(numbers: &[i32], delim: i32) -> (res: Vec<i32>)
    ensures
        res@ == intersperse_seq(numbers@, delim),
{
    let n = numbers.len();
    if n == 0 {
        return Vec::new();
    }

    // Result length is 2n - 1 for n > 0
    let mut res = Vec::with_capacity(2 * n - 1);

    for (i, &x) in numbers.iter().enumerate()
        invariant
            n == numbers.len(),
            0 <= i <= n,
            res@ == intersperse_seq(numbers@.subrange(0, i as int), delim),
        decreases n - i,
    {
        if i > 0 {
            res.push(delim);
            assert(res@ == intersperse_seq(numbers@.subrange(0, i as int), delim).push(delim));
        }
        res.push(x);
        assert(numbers@[i as int] == x);
        assert(res@ == intersperse_seq(numbers@.subrange(0, (i + 1) as int), delim));
    }

    assert(numbers@.subrange(0, n as int) == numbers@);
    res
}

} // verus!

